def render_icon(name: str, color: str = "#4B5563", size: int = 24) -> str:
    """Return inline SVG HTML string for the requested icon."""
    path = ICONS.get(name, ICONS.get("star"))
    return f'''
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="{color}" style="width:{size}px; height:{size}px; display:inline-block; vertical-align:middle;">
        {path}
    </svg>
    '''

